#requires -Version 5.1
# Reviewed Edge additions. Never derive allowed destinations, risks or values from a request.
function Get-WinSlimExtendedEdgeContract {
 param([string]$Id)
 switch -CaseSensitive ($Id) {
  'EDGE-007' {return [pscustomobject]@{Name='AutoDiscardSleepingTabsEnabled';Value='1';Minimum=120;Maximum=0;Risk='Baixo';Dependencies=@('EDGE-006');Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Requer EDGE-006 ativo; guias descartadas são recarregadas ao retornar.'}}
  'EDGE-009' {return [pscustomobject]@{Name='SyncDisabled';Value='1';Minimum=77;Maximum=0;Risk='Médio';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Desativa sincronização, sem apagar dados locais. Não se aplica a perfil Microsoft pessoal.'}}
  'EDGE-010' {return [pscustomobject]@{Name='BrowserSignin';Value='0';Minimum=77;Maximum=0;Risk='Médio';Dependencies=@();Note='Desativa entrada no navegador, não login em sites. Prevalece sobre NonRemovableProfileEnabled; requer reinício.'}}
  'EDGE-013' {return [pscustomobject]@{Name='ShowMicrosoftRewards';Value='0';Minimum=88;Maximum=0;Risk='Baixo';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Oculta Rewards; documentação diverge entre descrição e suporte de conta pessoal. Efeito por conta não presumido.'}}
  'EDGE-014' {return [pscustomobject]@{Name='AutofillAddressEnabled';Value='0';Minimum=77;Maximum=155;Risk='Médio';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Depreciada, ainda suportada; migração futura para AutofillSettings exige revisão. Liberada somente até Edge 155 revisado. Não apaga endereços.'}}
  'EDGE-015' {return [pscustomobject]@{Name='AutofillCreditCardEnabled';Value='0';Minimum=77;Maximum=155;Risk='Médio';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Depreciada, ainda suportada; migração futura para AutofillSettings exige revisão. Liberada somente até Edge 155 revisado. Não apaga pagamentos.'}}
  'EDGE-017' {return [pscustomobject]@{Name='WebToBrowserSignInEnabled';Value='0';Minimum=133;Maximum=0;Risk='Baixo';Dependencies=@();Note='Desativa convite/entrada do site para o navegador. Complementa BrowserSignin, sem bloquear login em sites.'}}
  'EDGE-018' {return [pscustomobject]@{Name='UrlDiagnosticDataEnabled';Value='0';Minimum=122;Maximum=0;Risk='Baixo';Dependencies=@();Note='Só produz efeito quando DiagnosticData efetivo é OptionalData (2). Com EDGE-031=1 é redundante; reconhecimento não comprova efeito.'}}
  'EDGE-021' {return [pscustomobject]@{Name='Microsoft365CopilotChatIconEnabled';Value='0';Minimum=139;Maximum=0;Risk='Baixo';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Somente perfil corporativo Entra ID e Copilot no painel lateral. Sem conta corporativa, efeito não pode ser validado.'}}
  'EDGE-022' {return [pscustomobject]@{Name='NetworkPredictionOptions';Value='2';Minimum=77;Maximum=0;Risk='Baixo';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Valor 2 desativa predição de rede; valor 1 não é suportado. Complementa pré-carregamento de nova guia.'}}
  'EDGE-023' {return [pscustomobject]@{Name='NewTabPagePrerenderEnabled';Value='0';Minimum=85;Maximum=0;Risk='Baixo';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Desativa pré-carregamento de nova guia; não desativa toda navegação especulativa isoladamente.'}}
  'EDGE-026' {return [pscustomobject]@{Name='TextPredictionEnabled';Value='0';Minimum=104;Maximum=0;Risk='Baixo';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Desativa predição do serviço em campos elegíveis; sites podem oferecer predição própria.'}}
  'EDGE-027' {return [pscustomobject]@{Name='VisualSearchEnabled';Value='0';Minimum=95;Maximum=0;Risk='Baixo';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Não controla pesquisa visual em Captura da Web, gerida por WebCaptureEnabled.'}}
  'EDGE-028' {return [pscustomobject]@{Name='AutofillMembershipsEnabled';Value='0';Minimum=110;Maximum=0;Risk='Médio';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Desativa salvar/preencher associações; não apaga dados existentes.'}}
  'EDGE-029' {return [pscustomobject]@{Name='MicrosoftEditorProofingEnabled';Value='0';Minimum=105;Maximum=0;Risk='Médio';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Mantém corretores locais; sem efeito se SpellcheckEnabled ou corretor do usuário já estiver desligado.'}}
  'EDGE-030' {return [pscustomobject]@{Name='PaymentMethodQueryEnabled';Value='0';Minimum=80;Maximum=0;Risk='Baixo';Dependencies=@();Note='Suporte a perfil conectado a conta Microsoft pessoal n?o confirmado; consulte a pol?tica. Faz APIs de consulta informarem ausência de meios de pagamento; não remove meios salvos.'}}
  'EDGE-031' {return [pscustomobject]@{Name='DiagnosticData';Value='1';Minimum=122;Maximum=0;Risk='Baixo';Dependencies=@();Note='Envia somente diagnóstico obrigatório. Não é desativação de toda telemetria e torna EDGE-018 redundante.'}}
 }
}
